import { createRouter } from '@tanstack/react-router';
import { queryClient } from '../../api/queries/queryClient';
import { routeTree } from './routeTree.gen';

/**
 * Route tree is generated by @tanstack/router-plugin from ./routes (see
 * vite.config.ts); routeTree.gen.ts must never be hand-maintained.
 */
export const router = createRouter({
  routeTree,
  context: { queryClient },
  defaultPreload: 'intent',
  // Preloaded matches are stale immediately; data freshness belongs to the
  // Query cache (ensureQueryData in loaders), not to the route cache.
  defaultPreloadStaleTime: 0,
});

declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router;
  }
}
